"use client";

import Link from "next/link";
import { useState } from "react";

const links = [
  { label: "Jobs", href: "/jobs" },
  { label: "Courses", href: "/courses" },
  { label: "Interviews", href: "/interviews" },
];

export default function SiteHeader() {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <header className="relative z-50 border-b border-ink/15">
      <div className="flex h-20 items-center justify-between sm:h-24">
        <Link
          className="group flex items-center gap-3 text-[18px] font-bold tracking-[-0.04em]"
          href="/"
          onClick={() => setIsOpen(false)}
        >
          <span className="grid size-9 place-items-center bg-coral font-mono text-[11px] tracking-[-0.12em] text-paper transition-transform duration-300 group-hover:-rotate-6">
            AM
          </span>
          <span>Ask Me</span>
        </Link>

        <nav
          className="hidden items-center gap-8 text-[12px] font-medium sm:flex"
          aria-label="Main navigation"
        >
          {links.map((link) => (
            <Link
              className="relative py-2 text-muted transition-colors after:absolute after:inset-x-0 after:-bottom-1 after:h-px after:origin-left after:scale-x-0 after:bg-coral after:transition-transform hover:text-ink hover:after:scale-x-100"
              href={link.href}
              key={link.href}
            >
              {link.label}
            </Link>
          ))}
          <Link
            className="border border-ink px-4 py-2.5 transition-colors hover:bg-ink hover:text-paper"
            href="/interviews"
          >
            Start practicing{" "}
            <span className="ml-2 text-base" aria-hidden="true">
              ↗
            </span>
          </Link>
        </nav>

        <button
          className="inline-flex items-center gap-2 border border-ink px-3 py-2 text-[11px] font-mono uppercase tracking-[0.08em] sm:hidden"
          type="button"
          aria-expanded={isOpen}
          aria-controls="mobile-navigation"
          onClick={() => setIsOpen((open) => !open)}
        >
          <span>{isOpen ? "Close" : "Menu"}</span>
          <span className="text-base leading-none" aria-hidden="true">
            {isOpen ? "×" : "+"}
          </span>
        </button>
      </div>

      {isOpen && (
        <nav
          id="mobile-navigation"
          className="absolute inset-x-0 top-full border-b border-ink/15 bg-paper px-5 py-5 shadow-[0_14px_30px_rgba(23,35,35,.08)] sm:hidden"
          aria-label="Mobile navigation"
        >
          <div className="grid gap-1">
            {links.map((link, index) => (
              <Link
                className="flex items-center justify-between border-b border-ink/10 py-4 font-display text-2xl tracking-[-0.04em]"
                href={link.href}
                key={link.href}
                onClick={() => setIsOpen(false)}
              >
                <span>{link.label}</span>
                <span
                  className="font-sans text-lg text-coral"
                  aria-hidden="true"
                >
                  0{index + 1} ↗
                </span>
              </Link>
            ))}
          </div>
          <Link
            className="mt-5 flex items-center justify-between bg-ink px-4 py-3 text-[12px] font-bold text-paper"
            href="/interviews"
            onClick={() => setIsOpen(false)}
          >
            Start practicing{" "}
            <span className="text-base" aria-hidden="true">
              ↗
            </span>
          </Link>
        </nav>
      )}
    </header>
  );
}
